import 'swiper/css'
import 'swiper/css/pagination'
import 'swiper/css/navigation'

SwiperCore.use([Autoplay, Pagination, Navigation])

export default {
  name: 'HeroSection',
  components: {
    Vue3Marquee,
    Swiper,
    SwiperSlide
  },
  
  setup() {
