         subtitle: "Make Premier League matches accessible to fans with disabilities. Support improved facilities and services for an inclusive football community.",
         first_num: "1000+",
         first_label: "Fans Assisted",
         second_num: "20",
         second_label: "Stadiums Improved",
         cta_button: "Support Accessibility"
      },
       {
         id: 4,
         image: 'https://images.unsplash.com/photo-1522778119026-d647f0596c20?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80',
         title: "Football for Everyone",
         subtitle: "Help make Premier League matches affordable for all fans. Your contribution sponsors tickets for families and individuals who can't afford them.",
         first_num: "2500+",
         first_label: "Free Tickets Provided",
         second_num: "800+",
         second_label: "Families Helped",
         cta_button: "Sponsor Tickets"
      }
   ]);

   const imgArray = [
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/jpeg;base64,',
      'data:image/png;base64,',
      'data:image/jpeg;base64,',
      'data:image/jpeg;base64,',
      'data:image/png;base64,'
   ]

   return {
      contents,
      imgArray
   }
  },

  mounted() {
    this.initSwiper()
  },
  methods: {
    scrollTo(elementId) {
      document.getElementById(elementId).scrollIntoView({ behavior: 'smooth' });
    },
    initSwiper() {
      const swiperContainer = this.$refs.swiperContainer
      
      this.swiper = new SwiperCore(swiperContainer, {
        loop: true,
        autoplay: {
          delay: 6000,
          disableOnInteraction: false,
        },
        pagination: {
          el: '.swiper-pagination',
          clickable: true,
        },
        navigation: {
          nextEl: '.swiper-button-next',
          prevEl: '.swiper-button-prev',
        },
        effect: 'fade',
        fadeEffect: {
          crossFade: true
        }
      })
    },
    quickDonate(amount) {
      // Handle quick donation
      console.log(`Donating £${amount}`)
      // Redirect to payment gateway or open donation modal
      this.$emit('donate', { amount, type: 'quick' })
    },
    customDonate() {
      // Handle custom donation
      console.log('Opening custom donation form')
      this.$emit('donate', { type: 'custom' })
    }
  },
  beforeUnmount() {
    if (this.swiper) {
      this.swiper.destroy()
    }
  }
}
</script>

